def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def to_xy(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return int(v[0]), int(v[1])
        if isinstance(v, dict):
            for k1, k2 in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if k1 in v and k2 in v and is_num(v.get(k1)) and is_num(v.get(k2)):
                    return int(v.get(k1)), int(v.get(k2))
        return None

    def get_in(d, keys):
        cur = d
        for k in keys:
            if not isinstance(cur, dict):
                return None
            cur = cur.get(k)
        return cur

    def all_coords(obj):
        out = []
        if obj is None:
            return out
        if isinstance(obj, dict):
            xy = to_xy(obj)
            if xy is not None:
                out.append(xy)
            for v in obj.values():
                out.extend(all_coords(v))
        elif isinstance(obj, (list, tuple)):
            xy = to_xy(obj)
            if xy is not None:
                out.append(xy)
            else:
                for v in obj:
                    out.extend(all_coords(v))
        return out

    def unique(points):
        seen = set()
        out = []
        for p in points:
            if p not in seen:
                seen.add(p)
                out.append(p)
        return out

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    obs = observation if isinstance(observation, dict) else {}

    pos = None
    for keypath in [
        ("position",), ("pos",), ("agent_pos",), ("agent",), ("self",),
        ("you",), ("location",), ("loc",), ("me",)
    ]:
        v = get_in(obs, keypath)
        if isinstance(v, dict):
            pos = to_xy(v)
        else:
            pos = to_xy(v)
        if pos is not None:
            break
    if pos is None:
        pos = (0, 0)

    grid = obs.get("grid")
    width = obs.get("width")
    height = obs.get("height")
    if (width is None or height is None) and isinstance(grid, list) and grid:
        height = len(grid)
        width = len(grid[0]) if isinstance(grid[0], list) else None

    # Collect candidate targets from many possible schemas.
    resource_keys = ["resources", "resource", "food", "items", "gems", "coins", "targets", "objectives", "collectibles"]
    opponent_keys = ["enemies", "enemy", "opponents", "opponent", "players", "agents", "others"]
    territory_keys = ["territory", "cells", "tiles", "board", "map", "grid"]

    resources = []
    opponents = []
    territory = []

    for k in resource_keys:
        resources.extend(all_coords(obs.get(k)))
    for k in opponent_keys:
        opponents.extend(all_coords(obs.get(k)))
    for k in territory_keys:
        v = obs.get(k)
        if k == "grid" and isinstance(v, list):
            # Grid may contain encoded cells; skip raw scan unless coordinates are explicit elsewhere.
            continue
        territory.extend(all_coords(v))

    resources = unique(resources)
    opponents = unique([p for p in opponents if p != pos])
    territory = unique([p for p in territory if p != pos])

    # If task exposes explicit goal/target, prefer it.
    explicit_target = None
    for k in ("target", "goal", "objective", "destination", "next_target"):
        t = to_xy(obs.get(k))
        if t is not None:
            explicit_target = t
            break

    moves = [(-1, -1), (-1, 0), (-1, 1),
             (0, -1), (0, 0), (0, 1),
             (1, -1), (1, 0), (1, 1)]

    # Prefer staying inside bounds if known.
    def in_bounds(p):
        if width is not None and height is not None:
            return 0 <= p[0] < int(width) and 0 <= p[1] < int(height)
        return True

    # Heuristic mode detection.
    mode = "generic"
    if resources:
        mode = "resource"
    if opponents and not resources:
        mode = "pursuit"
    if territory and not resources and not opponents:
        mode = "territory"
    if explicit_target is not None:
        mode = "target"

    # Simple danger estimate from nearest opponent.
    nearest_opp = None
    if opponents:
        nearest_opp = min(opponents, key=lambda p: md(pos, p))
    danger = md(pos, nearest_opp) if nearest_opp is not None else 999

    best_move = (0, 0)
    best_score = None

    for dx, dy in moves:
        np = (pos[0] + dx, pos[1] + dy)
        if not in_bounds(np):
            continue

        score = 0.0

        # Prefer movement over idle slightly.
        if dx == 0 and dy == 0:
            score -= 0.05

        if mode == "target" and explicit_target is not None:
            score -= md(np, explicit_target)

        elif mode == "resource" and resources:
            d = min(md(np, r) for r in resources)
            score -= 2.0 * d

            # If moving closer, reward.
            curd = min(md(pos, r) for r in resources)
            if d < curd:
                score += 0.5

        elif mode == "pursuit" and opponents:
            d = min(md(np, e) for e in opponents)
            curd = min(md(pos, e) for e in opponents)

            # Evade if close; otherwise approach a bit.
            if danger <= 2:
                score += 2.0 * d
            else:
                score -= 0.8 * d

            if d > curd:
                score += 0.2

        elif mode == "territory" and territory:
            d = min(md(np, t) for t in territory)
            score -= 1.2 * d

        else:
            # Generic: prefer center-ish and exploration away from origin.
            center = None
            if width is not None and height is not None:
                center = (int(width) // 2, int(height) // 2)
            if center is not None:
                score -= 0.25 * md(np, center)
            score += 0.02 * (abs(np[0]) + abs(np[1]))

        # Small safety bias away from nearest opponent when threatened.
        if nearest_opp is not None:
            d = md(np, nearest_opp)
            if danger <= 2:
                score += 1.5 * d
            elif danger <= 4:
                score += 0.3 * d

        # Mild preference for diagonal/orthogonal mix? none.

        if best_score is None or score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

